<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli') { http_response_code(404); exit; }
$root=dirname(__DIR__);$env=[];
foreach(file($root.'/.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){if(str_starts_with(trim($line),'#'))continue;[$key,$value]=array_pad(explode('=',$line,2),2,'');$env[trim($key)]=trim($value,' "');}
if(!in_array($env['DB_HOST']??'', ['localhost','127.0.0.1'],true))throw new RuntimeException('This migration is restricted to localhost.');
$db=new PDO('mysql:host='.$env['DB_HOST'].';dbname='.$env['DB_DATABASE'].';charset=utf8mb4',$env['DB_USERNAME'],$env['DB_PASSWORD'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$columnExists=static function(string $table,string $column)use($db):bool{$q=$db->prepare('SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?');$q->execute([$table,$column]);return(bool)$q->fetchColumn();};
if(!$columnExists('restaurants','delivery_minimum')){$db->exec('ALTER TABLE restaurants ADD COLUMN delivery_minimum DECIMAL(12,2) NOT NULL DEFAULT 1000.00 AFTER service_charge_percent');echo "Added restaurants.delivery_minimum (default LKR 1,000.00).".PHP_EOL;}else echo "restaurants.delivery_minimum already exists.".PHP_EOL;
if(!$columnExists('orders','online_payment_method')){$db->exec("ALTER TABLE orders ADD COLUMN online_payment_method ENUM('CASH_ON_DELIVERY','PAY_AT_PICKUP','ONLINE_PAYMENT') NULL AFTER delivery_notes");echo "Added orders.online_payment_method.".PHP_EOL;}else echo "orders.online_payment_method already exists.".PHP_EOL;
if(!$columnExists('restaurant_customers','origin')){$db->exec("ALTER TABLE restaurant_customers ADD COLUMN origin ENUM('MANAGER','ONLINE_REGISTRATION','ONLINE_GUEST','POS','LEGACY') NOT NULL DEFAULT 'LEGACY' AFTER address");$db->exec("ALTER TABLE restaurant_customers MODIFY COLUMN origin ENUM('MANAGER','ONLINE_REGISTRATION','ONLINE_GUEST','POS','LEGACY') NOT NULL DEFAULT 'MANAGER'");echo "Added restaurant_customers.origin; existing records marked LEGACY.".PHP_EOL;}else echo "restaurant_customers.origin already exists.".PHP_EOL;
$table=$db->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$table->execute(['online_customer_accounts']);
if(!$table->fetchColumn()){$db->exec("CREATE TABLE online_customer_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restaurant_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_online_account_customer (restaurant_id,customer_id), FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY (customer_id) REFERENCES restaurant_customers(id) ON DELETE CASCADE) ENGINE=InnoDB");echo "Created online_customer_accounts.".PHP_EOL;}else echo "online_customer_accounts already exists.".PHP_EOL;
